class Solution {public:
 int minMoves(vector<string>& classroom,int energy){
  int m=classroom.size(),n=classroom[0].size(),sx=-1,sy=-1,L=0;
  vector<vector<int>> id(m,vector<int>(n,-1));
  for(int i=0;i<m;++i)for(int j=0;j<n;++j){if(classroom[i][j]=='S'){sx=i;sy=j;}if(classroom[i][j]=='L')id[i][j]=L++;}
  int masks=1<<L;vector<int> dist(m*n*masks*(energy+1),-1);
  auto key=[&](int x,int y,int mask,int e){return (((x*n+y)*masks+mask)*(energy+1)+e);};
  queue<array<int,4>> q;q.push({sx,sy,0,energy});dist[key(sx,sy,0,energy)]=0;
  int dx[]={1,-1,0,0},dy[]={0,0,1,-1};
  while(!q.empty()){
   auto a=q.front();q.pop();int x=a[0],y=a[1],mask=a[2],e=a[3],d=dist[key(x,y,mask,e)];
   if(mask==masks-1)return d;
   if(!e)continue;
   for(int t=0;t<4;++t){int xx=x+dx[t],yy=y+dy[t];
    if(xx<0||xx>=m||yy<0||yy>=n||classroom[xx][yy]=='X')continue;
    int ne=classroom[xx][yy]=='R'?energy:e-1,nmask=mask;
    if(id[xx][yy]>=0)nmask|=1<<id[xx][yy];
    int z=key(xx,yy,nmask,ne);if(dist[z]<0){dist[z]=d+1;q.push({xx,yy,nmask,ne});}
   }
  }return -1;
 }
};
